module LPDensityTest

using Test
using KernelSmoothing
using KernelSmoothing: _cjmG
using Distributions: Normal, Exponential, quantile as nquantile, pdf as npdf
using LinearAlgebra: diag, eigvals, Symmetric
using Random: MersenneTwister

# reference values from lpdensity 3.0.1, generated by data/lpdensity_golden.R
include(joinpath(@__DIR__, "data", "lpdensity_golden.jl"))

const I = 1:500
const XN = round.(nquantile.(Normal(), mod.(I .* 0.6180339887498949, 1)) .+ 0.3 .* sin.(I .^ 2); digits = 2)
const XE = -log.(1 .- mod.(I .* 0.7548776662466927, 1))
const W = 1.0 .+ mod.(I, 3)
const K = Dict("triangular" => TriangularKernel(), "epanechnikov" => EpanechnikovKernel(), "uniform" => UniformKernel())

@testset "agrees with lpdensity" begin
  for c in LPDENSITY
    x = c.data == :xn ? XN : XE
    m = fit(LocalPolynomialDensity, x; weights = c.weighted ? W : nothing, points = c.grid, degree = c.p,
            derivative = c.v - 1, kernel = K[c.kernel], bandwidth = c.rot ? NormalReference() : c.bw[1],
            minobs = c.rot ? c.p + 21 : 0)
    # R integrates the kernel constants of the rule of thumb numerically, to about 1e-7
    tol = c.rot ? 1e-6 : 1e-10
    @test m.h ≈ c.bw rtol = tol
    @test m.nwindow == c.nh
    @test m.nunique == c.nhu
    @test m.estimate ≈ c.f_p rtol = tol
    @test m.estimate_bc ≈ c.f_q rtol = tol
    @test m.se ≈ c.se_p rtol = tol
    @test m.se_rbc ≈ c.se_q rtol = tol
    @test vcov(m) ≈ c.cov_p rtol = tol
  end
end

@testset "boundary adaptivity" begin
  # an exponential density: the estimate at the boundary 0 is consistent, unlike a KDE
  x = rand(MersenneTwister(1), Exponential(), 20_000)
  m = fit(LocalPolynomialDensity, x; points = [0.0, 0.5, 1.0], bandwidth = 0.3)
  @test m.estimate ≈ npdf.(Exponential(), [0.0, 0.5, 1.0]) rtol = 0.05
  f = fit(KDE, x; bandwidth = 0.3)
  @test pdf(f, 0.0) < 0.7   # a kernel density estimate loses about half the mass at the boundary
  # the bias-corrected estimate of order p + 1 reproduces a density that is a polynomial of order p + 1
  # on the window: the uniform density, where the distribution function is linear
  u = collect(range(0, 1; length = 2001))
  mu = fit(LocalPolynomialDensity, u; points = [0.0, 0.5, 1.0], bandwidth = 0.2, minobs = 0)
  @test mu.estimate ≈ [1, 1, 1] rtol = 1e-3
  @test mu.estimate_bc ≈ [1, 1, 1] rtol = 1e-3
end

@testset "kernel constants" begin
  # G of lpdensity for the triangular kernel, exactly (R integrates numerically)
  G = _cjmG(TriangularKernel(), 2)
  @test G ≈ [-7/30 1/12 -0.053174603174603174; 1/12 0.020634920634920634 1/72; -0.053174603174603174 1/72 -0.00992063492063492] rtol = 1e-12
  @test G ≈ G'
end

@testset "interface" begin
  m = fit(LocalPolynomialDensity, XN)
  @test length(m.points) == 19 && m.points[1] ≈ nquantile(XN, 0.05)
  @test m.selection.rule == NormalReference()
  C = vcov(m; method = RobustBiasCorrected())
  @test sqrt.(diag(C)) ≈ m.se_rbc rtol = 1e-10
  @test minimum(eigvals(Symmetric(C))) >= -1e-12 * maximum(diag(C))
  b = confband(m; rng = MersenneTwister(2))
  @test all(b.lower .< m.estimate_bc .< b.upper) && b.critical > 1.96
  t = coeftable(m)
  @test t.estimate == m.estimate && t.upper_rbc == confint(m)[:, 2]
  @test coef(m) == m.estimate && stderror(m; method = RobustBiasCorrected()) == m.se_rbc
  @test nobs(m) == 500 && bandwidth(m) == m.h
  @test occursin("Local polynomial density", sprint(show, MIME("text/plain"), m))
  @test occursin("LocalPolynomialDensity", sprint(show, m))
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; degree = 1, derivative = 1)
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; kernel = GaussianKernel(), bandwidth = 0.5)
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; bandwidth = SheatherJones())
  @test_throws ArgumentError confint(m; method = Honest(1.0))
end

end
